<template>
  <div>
    <div class="metric-grid">
      <div class="metric-card"><span>待审核</span><strong>{{ counts.pending || 0 }}</strong><small>资料变更后重新审核</small></div>
      <div class="metric-card"><span>30天内到期</span><strong>{{ counts.expiring || 0 }}</strong><small>需要续证跟踪</small></div>
      <div class="metric-card"><span>已过期</span><strong>{{ counts.expired || 0 }}</strong><small>不能作为有效准入依据</small></div>
      <div class="metric-card"><span>有效资质</span><strong>{{ counts.valid || 0 }}</strong><small>已审核且在有效期内</small></div>
    </div>
    <div class="table-toolbar">
      <el-input v-model.trim="keyword" clearable placeholder="供应商、资质类型、证书编号或发证机构" @keyup.enter.native="search" @clear="search"/>
      <el-select v-model="status" clearable placeholder="全部有效状态" @change="search"><el-option v-for="item in statuses" :key="item.value" :label="item.label" :value="item.value"/></el-select>
      <el-button icon="el-icon-search" @click="search">查询</el-button><el-button type="primary" @click="open()">新增资质</el-button>
    </div>
    <el-table v-loading="loading" :data="items" border empty-text="暂无供应商资质">
      <el-table-column prop="supplier_code" label="供应商编码" width="135"/><el-table-column prop="supplier_name" label="供应商" min-width="150"/>
      <el-table-column prop="qualification_type" label="资质类型" min-width="150"/><el-table-column prop="certificate_no" label="证书编号" min-width="140"/>
      <el-table-column prop="expires_on" label="到期日" width="110"/><el-table-column label="有效状态" width="105"><template slot-scope="s"><el-tag :type="statusType(s.row.effective_status)">{{ statusName(s.row.effective_status) }}</el-tag></template></el-table-column>
      <el-table-column label="版本/附件" min-width="150"><template slot-scope="s">V{{ s.row.version }} · <el-button v-if="s.row.attachment_name" type="text" @click="download(s.row)">{{ s.row.attachment_name }}</el-button><span v-else>未上传</span></template></el-table-column>
      <el-table-column label="操作" width="245" fixed="right"><template slot-scope="s"><el-button type="text" @click="open(s.row)">编辑</el-button><label class="el-button el-button--text" style="padding:0 6px"><span>上传附件</span><input type="file" hidden accept=".pdf,.docx,.xlsx,.png,.jpg,.jpeg" @change="upload(s.row,$event)"/></label><el-button type="text" @click="review(s.row)">审核</el-button><el-button type="text" @click="history(s.row)">历史</el-button><el-button type="text" class="danger-link" @click="remove(s.row)">删除</el-button></template></el-table-column>
    </el-table>
    <div class="pagination-row"><span>共 {{ pagination.total }} 条</span><el-pagination background layout="sizes,prev,pager,next" :page-sizes="[10,20,50]" :current-page="pagination.page" :page-size="pagination.page_size" :total="pagination.total" @current-change="changePage" @size-change="changeSize"/></div>

    <el-dialog :title="form.id?'编辑供应商资质':'新增供应商资质'" :visible.sync="visible" width="700px" append-to-body :close-on-click-modal="false"><el-form ref="form" :model="form" :rules="rules" label-width="105px">
      <el-form-item label="供应商" prop="supplier_id"><el-select v-model="form.supplier_id" filterable :disabled="!!form.id" style="width:100%"><el-option v-for="s in suppliers" :key="s.id" :label="`${s.code} · ${s.name}`" :value="s.id"/></el-select></el-form-item>
      <el-row :gutter="16"><el-col :span="12"><el-form-item label="资质类型" prop="qualification_type"><el-input v-model.trim="form.qualification_type" placeholder="如 ISO 9001、特种设备许可"/></el-form-item></el-col><el-col :span="12"><el-form-item label="证书编号"><el-input v-model.trim="form.certificate_no"/></el-form-item></el-col></el-row>
      <el-form-item label="发证机构"><el-input v-model.trim="form.issuing_authority"/></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="生效日期"><el-date-picker v-model="form.valid_from" type="date" value-format="yyyy-MM-dd" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="到期日期"><el-date-picker v-model="form.expires_on" type="date" value-format="yyyy-MM-dd" style="width:100%"/></el-form-item></el-col></el-row>
      <el-form-item label="资料说明"><el-input v-model.trim="form.review_note" type="textarea" :rows="3" maxlength="1000" show-word-limit/></el-form-item><el-alert title="新增或修改后状态为待审核；上传证明文件后，系统管理员或采购经理才能审核通过。" type="info" :closable="false"/>
    </el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></span></el-dialog>

    <el-dialog title="供应商资质审核" :visible.sync="reviewVisible" width="620px" append-to-body :close-on-click-modal="false"><template v-if="selected"><p>{{ selected.supplier_name }} · {{ selected.qualification_type }} · V{{ selected.version }}</p><el-alert v-if="!selected.attachment_name" title="尚未上传证明文件，不能审核通过" type="warning" :closable="false"/><el-form label-width="95px"><el-form-item label="审核结论"><el-radio-group v-model="decision.status"><el-radio label="approved">审核通过</el-radio><el-radio label="rejected">驳回</el-radio><el-radio label="suspended">暂停</el-radio></el-radio-group></el-form-item><el-form-item label="审核说明"><el-input v-model.trim="decision.note" type="textarea" :rows="4" maxlength="1000"/></el-form-item></el-form></template><span slot="footer"><el-button @click="reviewVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="decide">保存审核</el-button></span></el-dialog>

    <el-dialog title="资质版本历史" :visible.sync="historyVisible" width="820px" append-to-body><el-table :data="historyItems" border><el-table-column prop="version" label="版本" width="70"/><el-table-column label="动作" width="100"><template slot-scope="s">{{ actionName(s.row.action) }}</template></el-table-column><el-table-column prop="snapshot.review_status" label="审核状态" width="100"/><el-table-column prop="snapshot.expires_on" label="到期日" width="110"/><el-table-column prop="snapshot.attachment_name" label="附件" min-width="160"/><el-table-column prop="actor_id" label="操作人" width="120"/><el-table-column prop="created_at" label="时间" min-width="160"/></el-table><span slot="footer"><el-button @click="historyVisible=false">关闭</el-button></span></el-dialog>
  </div>
</template>
<script>
import {api,fetchMasterData} from '../api/client';
const fresh=()=>({id:'',supplier_id:'',qualification_type:'',certificate_no:'',issuing_authority:'',valid_from:null,expires_on:null,review_note:''});
export default {props:{supplierId:{type:String,default:''}},data:()=>({items:[],suppliers:[],counts:{},keyword:'',status:'',loading:false,saving:false,visible:false,reviewVisible:false,historyVisible:false,form:fresh(),selected:null,decision:{status:'approved',note:''},historyItems:[],pagination:{page:1,page_size:10,total:0},statuses:[{value:'pending',label:'待审核'},{value:'valid',label:'有效'},{value:'expiring',label:'30天内到期'},{value:'expired',label:'已过期'},{value:'rejected',label:'已驳回'},{value:'suspended',label:'已暂停'}],rules:{supplier_id:[{required:true,message:'请选择供应商',trigger:'change'}],qualification_type:[{required:true,min:2,message:'请输入资质类型',trigger:'blur'}]}}),async created(){const result=await fetchMasterData('suppliers',{page:1,page_size:100,unfiltered:true});this.suppliers=result.items;await this.load();},methods:{error(e){this.$message.error(e.response?.data?.detail||'操作失败');},statusName(v){return {pending:'待审核',valid:'有效',expiring:'即将到期',expired:'已过期',rejected:'已驳回',suspended:'已暂停'}[v]||v;},statusType(v){return {valid:'success',expiring:'warning',expired:'danger',rejected:'danger',suspended:'info',pending:'warning'}[v]||'info';},actionName(v){return {create:'创建',update:'资料修改',attachment:'附件更新',review:'审核'}[v]||v;},async load(){this.loading=true;try{const r=(await api.get('/supplier-qualifications',{params:{...this.pagination,supplier_id:this.supplierId,keyword:this.keyword,effective_status:this.status}})).data;this.items=r.items;this.pagination.total=r.total;this.counts=r.counts;}catch(e){this.error(e);}finally{this.loading=false;}},search(){this.pagination.page=1;this.load();},changePage(v){this.pagination.page=v;this.load();},changeSize(v){this.pagination.page_size=v;this.search();},open(row){this.form=row?{...row}:{...fresh(),supplier_id:this.supplierId};this.visible=true;this.$nextTick(()=>this.$refs.form&&this.$refs.form.clearValidate());},save(){this.$refs.form.validate(async valid=>{if(!valid)return;this.saving=true;const payload={qualification_type:this.form.qualification_type,certificate_no:this.form.certificate_no||'',issuing_authority:this.form.issuing_authority||'',valid_from:this.form.valid_from||null,expires_on:this.form.expires_on||null,review_note:this.form.review_note||''};try{if(this.form.id)await api.patch('/supplier-qualifications/'+this.form.id,payload);else await api.post('/suppliers/'+this.form.supplier_id+'/qualifications',payload);this.visible=false;await this.load();this.$message.success('供应商资质已保存');}catch(e){this.error(e);}finally{this.saving=false;}});},async upload(row,event){const file=event.target.files[0];event.target.value='';if(!file)return;const data=new FormData();data.append('file',file);try{await api.post('/supplier-qualifications/'+row.id+'/attachment',data,{headers:{'Content-Type':'multipart/form-data'}});await this.load();this.$message.success('附件已上传，资质重新进入待审核');}catch(e){this.error(e);}},async download(row){try{const r=await api.get('/supplier-qualifications/'+row.id+'/attachment',{responseType:'blob'});const url=URL.createObjectURL(r.data),a=document.createElement('a');a.href=url;a.download=row.attachment_name;a.click();URL.revokeObjectURL(url);}catch(e){this.error(e);}},review(row){this.selected=row;this.decision={status:row.review_status==='pending'?'approved':row.review_status,note:row.review_note||''};this.reviewVisible=true;},async decide(){if(this.decision.status==='rejected'&&!this.decision.note)return this.$message.warning('驳回必须填写原因');this.saving=true;try{await api.post('/supplier-qualifications/'+this.selected.id+'/decision',this.decision);this.reviewVisible=false;await this.load();this.$message.success('审核结果已保存');}catch(e){this.error(e);}finally{this.saving=false;}},async history(row){try{this.historyItems=(await api.get('/supplier-qualifications/'+row.id+'/history',{params:{page:1,page_size:100}})).data.items;this.historyVisible=true;}catch(e){this.error(e);}},async remove(row){try{await this.$confirm('确认删除该供应商资质及其版本记录？','删除资质',{type:'warning'});await api.delete('/supplier-qualifications/'+row.id);await this.load();this.$message.success('资质已删除');}catch(e){if(e!=='cancel')this.error(e);}}}};
</script>
